/**
 * Get the difference in the given unit between two dates.
 *
 * @param Unit|string $unit
 */
public function diffInUnit(CarbonInterface $start, CarbonInterface $end, Unit|string $unit, bool $absolute = false, bool $utc = false): float
{
    $clock = $this->getClock();
    $factory = $clock?->getFactory() ?? FactoryImmutable::getDefaultInstance();
    $locale = $factory->getSettings()['locale'] ?? 'en';
    $language = new Language($locale);
    $normalizedLocale = $language->getCode();

    if ($language->getVariant()) {
        $normalizedLocale .= '_'.$language->getVariant();
    }

    if ($language->getRegion()) {
        $normalizedLocale .= '_'.$language->getRegion();
    }

    $rawUnit = $unit instanceof Unit ? $unit->value : rtrim((string) $unit, 'z');

    try {
        $resolvedUnit = Unit::fromName($rawUnit, $normalizedLocale);
        $unitName = Carbon::pluralUnit($resolvedUnit->value);
    } catch (Throwable) {
        $unitName = Carbon::pluralUnit($rawUnit);
    }

    $startTimezone = CarbonTimeZone::instance($start->getTimezone());
    $endTimezone = CarbonTimeZone::instance($end->getTimezone());

    if (
        !$utc
        && $startTimezone
        && $endTimezone
        && $startTimezone->getName() !== $endTimezone->getName()
    ) {
        $start = $start->avoidMutation()->utc();
        $end = $end->avoidMutation()->utc();
    }

    $start = $start->avoidMutation()->setDateTime(
        $start->year,
        $start->month,
        $start->day,
        $start->hour,
        $start->minute,
        $start->second,
        $start->micro,
    );
    $end = $end->avoidMutation()->setDateTime(
        $end->year,
        $end->month,
        $end->day,
        $end->hour,
        $end->minute,
        $end->second,
        $end->micro,
    );

    $method = 'diffIn'.$unitName;

    if (!method_exists($start, $method)) {
        throw new UnknownUnitException($unitName);
    }

    return $start->$method($end, $absolute, $utc);
}

/**
 * Get amount of given unit equivalent to the interval.
 *
 * @param string $unit
 *
 * @throws UnknownUnitException|UnitNotConfiguredException
 *
 * @return float
 */
public function total(string $unit): float
{
    $realUnit = $unit = strtolower($unit);

    if (\in_array($unit, ['days', 'weeks'])) {
        $realUnit = 'dayz';
    } elseif (!\in_array($unit, ['microseconds', 'milliseconds', 'seconds', 'minutes', 'hours', 'dayz', 'months', 'years'])) {
        throw new UnknownUnitException($unit);
    }

    $this->checkStartAndEnd();

    if ($this->startDate && $this->endDate) {
        return $this->diffInUnit($this->startDate, $this->endDate, $unit);
    }

    $result = 0;
    $cumulativeFactor = 0;
    $unitFound = false;
    $factors = self::getFlipCascadeFactors();
    $daysPerWeek = (int) static::getDaysPerWeek();

    $values = [
        'years' => $this->years,
        'months' => $this->months,
        'weeks' => (int) ($this->d / $daysPerWeek),
        'dayz' => fmod($this->d, $daysPerWeek),
        'hours' => $this->hours,
        'minutes' => $this->minutes,
        'seconds' => $this->seconds,
        'milliseconds' => (int) ($this->microseconds / Carbon::MICROSECONDS_PER_MILLISECOND),
        'microseconds' => $this->microseconds % Carbon::MICROSECONDS_PER_MILLISECOND,
    ];

    if (isset($factors['dayz']) && $factors['dayz'][0] !== 'weeks') {
        $values['dayz'] += $values['weeks'] * $daysPerWeek;
        $values['weeks'] = 0;
    }

    foreach ($factors as $source => [$target, $factor]) {
        if ($source === $realUnit) {
            $unitFound = true;
            $value = $values[$source];
            $result += $value;
            $cumulativeFactor = 1;
        }

        if ($factor === false) {
            if ($unitFound) {
                break;
            }

            $result = 0;
            $cumulativeFactor = 0;

            continue;
        }

        if ($target === $realUnit) {
            $unitFound = true;
        }

        if ($cumulativeFactor) {
            $cumulativeFactor *= $factor;
            $result += $values[$target] * $cumulativeFactor;

            continue;
        }

        $value = $values[$source];

        $result = ($result + $value) / $factor;
    }

    if (isset($target) && !$cumulativeFactor) {
        $result += $values[$target];
    }

    if (!$unitFound) {
        throw new UnitNotConfiguredException($unit);
    }

    if ($this->invert) {
        $result *= self::NEGATIVE;
    }

    if ($unit === 'weeks') {
        $result /= $daysPerWeek;
    }

    // Cast as int numbers with no decimal part
    return fmod($result, 1) === 0.0 ? (int) $result : $result;
}

